#include <stdio.h>
#include <string.h>

const char *USAGE =
"   ___  _____  ____\n"
"  / _ \/  _/ |/_/ /____ ______ _      Made with love by Eliuk Blau\n"
" / ___// /_>  </ __/ -_) __/  ' \\ https://github.com/eliukblau/pixterm\n"
"/_/  /___/_/|_|\\__\\/\\__/_/ /_/_/_/                1.3.2\n"
