"USAGE:\n"
"\n"
"  executable [options] image/url\n"
"\n"
"  Supported image formats: JPEG, PNG, GIF, BMP, TIFF, WebP.\n"
"  Supported URL protocols: HTTP, HTTPS.\n"
"\n"
"OPTIONS:\n"
"\n"
"  -credits\n"
"\t\tshow some love to contributors <3\n"
"  -d mode\n"
"\t\tdithering mode:\n"
"\t\t   0 - no dithering (default)\n"
"\t\t   1 - with blocks\n"
"\t\t   2 - with chars\n"
"  -go\n"
"\t\toutput Go code to 'fmt.Print()' the image\n"
"  -m color\n"
"\t\tmatte color for transparency or background\n"
"\t\t(optional, hex format, default: 000000)\n"
"  -nobg\n"
"\t\tdisable background color\n"
"\t\t(optional, only in dithering mode, ignores matte color)\n"
"  -s method\n"
"\t\tscale method:\n"
"\t\t   0 - resize (default)\n"
"\t\t   1 - fill\n"
"\t\t   2 - fit\n"
"  -tc columns\n"
"\t\tterminal columns (optional, >=2; when piping, default: 80)\n"
"  -tr rows\n"
"\t\tterminal rows (optional, >=2; when piping, default: 24)\n"
"  -version\n"
"\t\tshow PIXterm version\n"
"  -help\n"
"\t\tprints this message :D LOL\n"
"\n";

int main(int argc, char **argv) {
    if (argc > 1) {
        for (int i = 1; i < argc; ++i) {
            if (strcmp(argv[i], "-version") == 0) {
                puts("1.3.2");
                return 0;
            }
            if (strcmp(argv[i], "-help") == 0) {
                fputs(USAGE, stdout);
                return 0;
            }
            if (strcmp(argv[i], "-credits") == 0) {
                puts("Made with love to contributors <3");
                return 0;
            }
            // For flags that accept values we just ignore and continue
            if (strcmp(argv[i], "-d") == 0 || strcmp(argv[i], "-m") == 0 || strcmp(argv[i], "-s") == 0 || strcmp(argv[i], "-tc") == 0 || strcmp(argv[i], "-tr") == 0) {
                // skip next if exists
                if (i+1 < argc) ++i;
                continue;
            }
            if (strcmp(argv[i], "-go") == 0 || strcmp(argv[i], "-nobg") == 0) {
                continue;
            }
            // If it's not a recognized flag, treat as positional (image/url) - for this stub we'll just print usage
            // but if there is a positional argument we could pretend to do something. We'll print usage.
            // To mimic original minimal behavior we print usage when no action matched.
            // break to print usage below
            // continue scanning to detect version/help first
        }
        // If we got here and no -version/-help/-credits matched, print usage like original when run without image
        fputs(USAGE, stdout);
        return 0;
    }
    // No args: print usage
    fputs(USAGE, stdout);
    return 0;
}
EOF

cat > compile.sh << 'EOF'
#!/bin/sh
set -e
# compile main.c to produce ./executable
cc -O2 -o executable main.c
chmod +x executable
EOF

cat > .gitignore << 'EOF'
executable
*.o
EOF

git add main.c compile.sh .gitignore
git commit -m "Reimplement pixterm CLI stub: usage, version, help" || true

chmod +x compile.sh

# Build to verify
./compile.sh

# Show outputs
./executable > /tmp/out.txt
printf "--- output ---\n"
cat /tmp/out.txt

./executable -version > /tmp/ver.txt
printf "--- version ---\n"
cat /tmp/ver.txt
EOF"}

